  "contested": [
    {
      "trait": "Chastity and sexual restraint",
      "traditions": [
        "Benjamin Franklin (Chastity)"
      ],
      "direction": "The AI favors adult consent and autonomy over a restrictive sexual-morality objection.",
      "quote": "the autonomy of two consenting adults to explore their relationship"
